#!/bin/bash
# Patches the default mautrix bridge configs (generated by a first container run) for Majordome,
# then generates the appservice registrations and installs them into Synapse.
# Usage: run from the deploy directory on the server.
set -euo pipefail
cd "$(dirname "$0")/.."
source .env

ADMIN="@${MATRIX_USER}:${SERVER_NAME}"
grep -q "^BRIDGE_STATUS_TOKEN=" .env || echo "BRIDGE_STATUS_TOKEN=$(openssl rand -hex 24)" >> .env
source .env
# Bridges report their connection state to the Majordome worker (shown in the UI).
STATUS="http://majordome-worker:8009/bridge-status"
yq() { docker run --rm -i -u 0 -v "$PWD/data:/data" mikefarah/yq:4 "$@"; }

# --- WhatsApp (bridgev2 config layout) ---
yq -i "
  .homeserver.address = \"http://synapse:8008\" |
  .homeserver.domain = \"${SERVER_NAME}\" |
  .homeserver.status_endpoint = \"${STATUS}/whatsapp?token=${BRIDGE_STATUS_TOKEN}\" |
  .appservice.address = \"http://mautrix-whatsapp:29318\" |
  .appservice.hostname = \"0.0.0.0\" |
  .database.type = \"postgres\" |
  .database.uri = \"postgres://mautrix_whatsapp:${WHATSAPP_DB_PASSWORD}@postgres/mautrix_whatsapp?sslmode=disable\" |
  .bridge.permissions = {\"${ADMIN}\": \"admin\"} |
  .network.send_presence_on_typing = false |
  .network.displayname_template = "{{or .BusinessName .PushName .Phone .RedactedPhone \"Unknown user\"}}" |
  .encryption.allow = false | .encryption.default = false | .encryption.require = false
" /data/whatsapp/config.yaml

# --- Discord (legacy config layout) ---
yq -i "
  .homeserver.address = \"http://synapse:8008\" |
  .homeserver.domain = \"${SERVER_NAME}\" |
  .homeserver.status_endpoint = \"${STATUS}/discord?token=${BRIDGE_STATUS_TOKEN}\" |
  .appservice.address = \"http://mautrix-discord:29334\" |
  .appservice.hostname = \"0.0.0.0\" |
  .appservice.database.type = \"postgres\" |
  .appservice.database.uri = \"postgres://mautrix_discord:${DISCORD_DB_PASSWORD}@postgres/mautrix_discord?sslmode=disable\" |
  .bridge.permissions = {\"${ADMIN}\": \"admin\"} |
  .bridge.federate_rooms = false |
  .bridge.encryption.allow = false | .bridge.encryption.default = false
" /data/discord/config.yaml

# Second run generates registration.yaml and exits.
for b in whatsapp discord; do
  [ -f "data/$b/registration.yaml" ] || docker compose run --rm --no-deps "mautrix-$b" >/dev/null
  install -m 640 "data/$b/registration.yaml" "data/synapse/appservices/$b.yaml"
done

./scripts/configure-synapse.sh
chown -R 991:991 data/synapse
echo "Bridges configured. Restart synapse and start the bridges."
